def shortestInInfinite(nums, target):
    n = len(nums)
    total = sum(nums)
    base = (target // total) * n
    rem = target % total
    if rem == 0:
        return base
    best = -1
    left = 0
    cur = 0
    for right in range(2 * n):
        cur += nums[right % n]
        while cur > rem:
            cur -= nums[left % n]
            left += 1
        if cur == rem:
            length = right - left + 1
            if best < 0 or length < best:
                best = length
    return -1 if best < 0 else base + best
